def build(world):
    blocked = set(world.blocked_tiles())
    occupied = set()

    for e in world.entities():
        if e.kind == "item-entity":
            continue
        if e.kind in ("furnace", "mining-drill"):
            ex = int(round(e.x - 1))
            ey = int(round(e.y - 1))
            occupied.update(((ex, ey), (ex + 1, ey), (ex, ey + 1), (ex + 1, ey + 1)))
        else:
            occupied.add((int(math.floor(e.x)), int(math.floor(e.y))))

    directions = ((1, 0, "E"), (-1, 0, "W"), (0, 1, "S"), (0, -1, "N"))
    start = world.tile()
    queues = {}

    for ox, oy in world.ore_tiles("iron-ore"):
        for dx in (ox - 1, ox):
            for dy in (oy - 1, oy):
                drill_cells = ((dx, dy), (dx + 1, dy), (dx, dy + 1), (dx + 1, dy + 1))
                if any(cell in blocked or cell in occupied for cell in drill_cells):
                    continue

                fy = dy + 2
                for fx in (dx, dx + 1):
                    furnace_cells = ((fx, fy), (fx + 1, fy), (fx, fy + 1), (fx + 1, fy + 1))
                    if any(cell in blocked or cell in occupied or cell in drill_cells
                           for cell in furnace_cells):
                        continue

                    layout = drill_cells + furnace_cells
                    low_x = min(start[0], dx, fx) - 5
                    high_x = max(start[0], dx + 1, fx + 1) + 5
                    low_y = min(start[1], dy, fy) - 5
                    high_y = max(start[1], dy + 1, fy + 1) + 5

                    queue = [start]
                    parent = {start: None}
                    parent_dir = {}
                    i = 0
                    while i < len(queue) and start not in parent:
                        here = queue[i]
                        i += 1
                        for step_x, step_y, direction in directions:
                            nxt = (here[0] + step_x, here[1] + step_y)
                            if (nxt in parent or nxt in blocked or nxt in occupied
                                    or nxt[0] < low_x or nxt[0] > high_x
                                    or nxt[1] < low_y or nxt[1] > high_y):
                                continue
                            parent[nxt] = here
                            parent_dir[nxt] = direction
                            queue.append(nxt)

                    if start in parent:
                        key = (dx, dy, fx, fy)
                        distance = len(queue) - 1
                        if key not in queues or distance < queues[key]:
                            queues[key] = distance

    chosen = None
    chosen_distance = None
    for key, distance in queues.items():
        if chosen is None or distance < chosen_distance:
            chosen = key
            chosen_distance = distance

    if chosen is None:
        return

    dx, dy, fx, fy = chosen
    parent = {}

    while world.tile() != start and len(parent) < 100:
        here = world.tile()
        found = False
        for point, first in parent.items():
            if point == here:
                found = True
                break
        if found:
            break

        for step_x, step_y, direction in directions:
            nxt = (here[0] + step_x, here[1] + step_y)
            if (nxt in parent or nxt in blocked or nxt in occupied
                    or nxt[0] < start[0] - 5 or nxt[0] > start[0] + 5
                    or nxt[1] < start[1] - 5 or nxt[1] > start[1] + 5):
                continue
            parent[nxt] = first
            break

    while world.tile() != start:
        here = world.tile()
        if here not in parent:
            break
        first = parent[here]
        if first == here:
            break

        direction = None
        for step_x, step_y, direction in directions:
            if (here[0] + step_x, here[1] + step_y) == first:
                break

        before = world.tile()
        world.move(direction, "step")
        after = world.tile()
        if after == before and world.decisions_left() > 0:
            parent[after] = first

    if world.tile() != start:
        return

    if not world.place("burner-mining-drill", dx, dy, "S"):
        return
    if not world.place("stone-furnace", fx, fy, "N"):
        return

    drill = None
    drill_distance = None
    furnace = None
    furnace_distance = None

    for e in world.entities():
        if e.kind == "mining-drill":
            distance = abs(e.x - (dx + 1)) + abs(e.y - (dy + 1))
            if drill is None or distance < drill_distance:
                drill = e
                drill_distance = distance
        elif e.kind == "furnace":
            distance = abs(e.x - (fx + 1)) + abs(e.y - (fy + 1))
            if furnace is None or distance < furnace_distance:
                furnace = e
                furnace_distance = distance

    if drill is None or furnace is None:
        return
    if not world.give(drill, "coal", 20):
        return
    if not world.give(furnace, "coal", 20):
        return

    waits = 0
    while waits < 180 and world.decisions_left() > 0:
        world.wait()
        waits += 1

