def build(world):
    def machine_blocked(x, y, blocked, entities):
        for tx in (x, x + 1):
            for ty in (y, y + 1):
                if (tx, ty) in blocked:
                    return True
        for e in entities:
            if e.kind == "item-entity":
                continue
            if e.kind == "wall":
                ex = int(math.floor(e.x))
                ey = int(math.floor(e.y))
                if x <= ex <= x + 1 and y <= ey <= y + 1:
                    return True
            else:
                ex = int(math.floor(e.x + 0.5))
                ey = int(math.floor(e.y + 0.5))
                if (ex, ey) in ((x, y), (x + 1, y), (x, y + 1), (x + 1, y + 1)):
                    return True
        return False

    def route(start, goal, obstacles):
        if start == goal:
            return []
        margin = 12
        min_x = min(start[0], goal[0]) - margin
        max_x = max(start[0], goal[0]) + margin
        min_y = min(start[1], goal[1]) - margin
        max_y = max(start[1], goal[1]) + margin
        queue = [start]
        previous = {start: None}
        directions = ((0, -1), (1, 0), (0, 1), (-1, 0))
        index = 0
        while index < len(queue):
            current = queue[index]
            index += 1
            for dx, dy in directions:
                nxt = (current[0] + dx, current[1] + dy)
                if nxt in previous:
                    continue
                if nxt[0] < min_x or nxt[0] > max_x:
                    continue
                if nxt[1] < min_y or nxt[1] > max_y:
                    continue
                if nxt in obstacles:
                    continue
                previous[nxt] = current
                if nxt == goal:
                    path = []
                    cursor = goal
                    while cursor != start:
                        path.append(cursor)
                        cursor = previous[cursor]
                    path.reverse()
                    return path
                queue.append(nxt)
        return None

    blocked = set(world.blocked_tiles())
    for e in world.entities():
        if e.kind == "wall":
            blocked.add((int(math.floor(e.x)), int(math.floor(e.y))))
        elif e.kind != "item-entity":
            ex = int(math.floor(e.x + 0.5))
            ey = int(math.floor(e.y + 0.5))
            blocked.add((ex, ey))

    start = world.tile()
    candidates = set()
    for ox, oy in world.ore_tiles("iron-ore"):
        for ax in (ox - 1, ox):
            for ay in (oy - 1, oy):
                for facing, fx, fy in (
                    ("N", ax, ay - 2),
                    ("E", ax + 2, ay),
                    ("S", ax, ay + 2),
                    ("W", ax - 2, ay),
                ):
                    if machine_blocked(ax, ay, blocked, world.entities()):
                        continue
                    if machine_blocked(fx, fy, blocked, world.entities()):
                        continue
                    candidates.add((ax, ay, facing, fx, fy))

    ordered = []
    for ax, ay, facing, fx, fy in candidates:
        ordered.append((
            abs(start[0] - ax) + abs(start[1] - ay),
            ax, ay, facing, fx, fy
        ))
    ordered = sorted(ordered)

    for score, ax, ay, facing, fx, fy in ordered:
        drill_tiles = {(ax, ay), (ax + 1, ay), (ax, ay + 1), (ax + 1, ay + 1)}
        furnace_tiles = {(fx, fy), (fx + 1, fy), (fx, fy + 1), (fx + 1, fy + 1)}
        obstacles = set(blocked)
        obstacles.update(drill_tiles)
        obstacles.update(furnace_tiles)

        while world.tile() != (ax, ay) and world.tile() != (fx, fy):
            here = world.tile()
            path_to_drill = route(here, (ax, ay), obstacles)
            path_to_furnace = route(here, (fx, fy), obstacles)
            if path_to_drill is None and path_to_furnace is None:
                break
            if path_to_drill is None:
                path = path_to_furnace
                destination = (fx, fy)
            elif path_to_furnace is None:
                path = path_to_drill
                destination = (ax, ay)
            else:
                if len(path_to_drill) <= len(path_to_furnace):
                    path = path_to_drill
                    destination = (ax, ay)
                else:
                    path = path_to_furnace
                    destination = (fx, fy)

            if len(path) == 0:
                break

            current = here
            first = path[0]
            dx = first[0] - current[0]
            dy = first[1] - current[1]
            if dx == 1:
                direction = "E"
            elif dx == -1:
                direction = "W"
            elif dy == 1:
                direction = "S"
            else:
                direction = "N"

            moved = world.move(direction, "step")
            if not moved:
                if world.tile() == current:
                    if direction == "E":
                        obstacles.add((current[0] + 1, current[1]))
                    elif direction == "W":
                        obstacles.add((current[0] - 1, current[1]))
                    elif direction == "S":
                        obstacles.add((current[0], current[1] + 1))
                    else:
                        obstacles.add((current[0], current[1] - 1))

        if world.tile() != (ax, ay) and world.tile() != (fx, fy):
            continue

        if not world.place("burner-mining-drill", ax, ay, facing):
            continue
        if not world.place("stone-furnace", fx, fy, "N"):
            return

        drill = None
        furnace = None
        drill_distance = None
        furnace_distance = None
        for e in world.entities():
            if e.kind == "mining-drill":
                distance = abs(e.x - (ax + 1)) + abs(e.y - (ay + 1))
                if drill_distance is None or distance < drill_distance:
                    drill = e
                    drill_distance = distance
            elif e.kind == "furnace":
                distance = abs(e.x - (fx + 1)) + abs(e.y - (fy + 1))
                if furnace_distance is None or distance < furnace_distance:
                    furnace = e
                    furnace_distance = distance

        if drill is not None:
            world.give(drill, "coal", 20)
        if furnace is not None:
            world.give(furnace, "coal", 20)
        return
